package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.io.IOException;
import java.math.*;
import java.math.BigInteger;
import java.nio.ByteBuffer;
import java.util.*;
import org.apache.commons.compress.archivers.zip.ZipEncoding;
import org.apache.commons.compress.archivers.zip.ZipEncodingHelper;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.fail;

public class TarUtils_parseOctal_TriageGen0Test {

    @Test
    public void testParseOctal_ValidSimple() {
        byte[] buffer = "000123".getBytes();
        long result = TarUtils.parseOctal(buffer, 0, 6);
        assertEquals(83L, result); // 1*64 + 2*8 + 3 = 64 + 16 + 3 = 83
    }

    @Test
    public void testParseOctal_WithLeadingSpaces() {
        byte[] buffer = "   0755".getBytes();
        long result = TarUtils.parseOctal(buffer, 0, 8);
        assertEquals(493L, result); // 7*64 + 5*8 + 5 = 448 + 40 + 5 = 493
    }

    @Test
    public void testParseOctal_WithTrailingNulAndSpaces() {
        // Buffer contains "0123", then a space, then a NUL
        byte[] buffer = {'0', '1', '2', '3', ' ', 0, 0};
        long result = TarUtils.parseOctal(buffer, 0, 7);
        assertEquals(67L, result); // 1*64 + 2*8 + 3 = 83? No. 1*64 + 2*8 + 3 = 83. 
        // Wait: 0*64 + 1*8 + 2*1 + 3? No, octal is base 8.
        // '0'->0, '1'->1, '2'->2, '3'->3. 
        // 0*8^3 + 1*8^2 + 2*8^1 + 3*8^0 = 0 + 64 + 16 + 3 = 83.
        // Let's re-verify the math in the code: result = (result << 3) + (currentByte - '0')
        // 0 << 3 + 0 = 0
        // 0 << 3 + 1 = 1
        // 1 << 3 + 2 = 10 (decimal)
        // 10 << 3 + 3 = 83 (decimal)
        assertEquals(83L, result);
    }

    @Test
    public void testParseOctal_ZeroBufferStart() {
        byte[] buffer = {0, 1, 2, 3};
        long result = TarUtils.parseOctal(buffer, 0, 4);
        assertEquals(0L, result);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParseOctal_LengthTooShort() {
        byte[] buffer = "01".getBytes();
        TarUtils.parseOctal(buffer, 0, 1);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParseOctal_InvalidDigit() {
        byte[] buffer = "0128".getBytes(); // '8' is invalid in octal
        TarUtils.parseOctal(buffer, 0, 4);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParseOctal_InvalidChar() {
        byte[] buffer = "012A".getBytes(); // 'A' is invalid
        TarUtils.parseOctal(buffer, 0, 4);
    }

    @Test
    public void testParseOctal_WithOffset() {
        byte[] buffer = {'X', 'X', '0', '7', ' ', 0};
        // offset 2, length 4 -> "07 "
        long result = TarUtils.parseOctal(buffer, 2, 4);
        assertEquals(7L, result);
    }

    @Test
    public void testParseOctal_AllSpacesAndNuls() {
        // Testing the while loop for trailing NULs and spaces where it might reduce end to start
        byte[] buffer = {' ', ' ', ' ', ' ', 0, 0};
        // length is 6. start becomes 4. end is 6. 
        // trailer is buffer[5] = 0. end becomes 5. 
        // trailer is buffer[4] = 0. end becomes 4.
        // loop start < end (4 < 4) fails.
        // Note: if start == end, the loop for digits doesn't run.
        // Since buffer[start] (buffer[0]) was ' ', it's not 0, so it enters skip leading spaces.
        // However, if the buffer is all spaces/nuls, we need to be careful.
        // The code says: if (buffer[start] == 0) return 0L;
        // If it's all spaces, start will increment until start == end.
        // Then end will decrement until end == start.
        // The result will be 0.
        long result = TarUtils.parseOctal(buffer, 0, 6);
        assertEquals(0L, result);
    }

    @Test
    public void testParseOctal_LargeValue() {
        // Max long value in octal? Let's just do a large one.
        // 777777777777777777 (octal)
        byte[] buffer = "777777777777777777".getBytes();
        long result = TarUtils.parseOctal(buffer, 0, buffer.length);
        // Check that it doesn't crash and returns a positive value
        assert(result > 0);
    }

    @Test
    public void testParseOctal_OnlyTrailingSpaces() {
        byte[] buffer = {'1', '2', ' ', ' '};
        long result = TarUtils.parseOctal(buffer, 0, 4);
        assertEquals(10L, result); // 1*8 + 2 = 10
    }
}
